let refreshing = null
async function authFetch(req) {
  let res = await fetch(req)
  if (res.status === 401) {
    refreshing ??= fetch("/refresh", { credentials: "include" })
    await refreshing.finally(() => { refreshing = null })
    res = await fetch(req) // retry once with the new access token
  }
  return res
}

import { randomBytes, createHash } from "crypto"
const sha256 = (s) => createHash("sha256").update(s).digest("hex")
// request: email the raw token, store only its hash
const token = randomBytes(32).toString("hex")
await db.resetTokens.insert({ userId, tokenHash: sha256(token), expiresAt: Date.now() + 30 * 60_000 })
// verify: look up by hash, check unused + not expired, then single-use delete
const row = await db.resetTokens.findByHash(sha256(input))
if (!row || row.used || row.expiresAt < Date.now()) throw new Error("invalid token")

// count failed attempts per account+IP in a rolling window (Redis)
const key = `login:fail:${email}:${ip}`
const fails = await redis.incr(key)
if (fails === 1) await redis.expire(key, 900)   // 15-min window
if (fails > 5) throw new Error("too many attempts, slow down")
